(10, 'NG-BAN-04', 'Sản phẩm', 2, 'Thanh hạt ngũ cốc', 'thanh-hat-ngu-coc', 135000, 'Thanh năng lượng từ yến mạch, hạt và mật ong, đóng gói từng thanh tiện mang theo.', 'images/products/thanh-hat-ngu-coc.webp', 1, 0, 0, '2026-09-15 09:23:00'),
(11, 'NG-GL-01', 'Sản phẩm', 3, 'Bún gạo lứt', 'bun-gao-lut', 98000, 'Bún khô 100% gạo lứt đỏ, sợi dai, không chất tẩy trắng.', 'images/products/bun-gao-lut.webp', 0, 1, 0, '2026-09-15 09:23:00'),
