(14, 'NG-HAT-04', 'Sản phẩm', 1, 'Hạt óc chó rang mộc', 'hat-oc-cho-rang-moc', 179000, 'Óc chó nửa nhân vàng sáng, rang mộc nhiệt độ thấp, giàu omega-3 thực vật.', 'images/products/hat-oc-cho-rang-moc.webp', 1, 0, 0, '2026-10-20 09:23:00'),
