(16, 'NG-GRA-03', 'Sản phẩm', 1, 'Granola trái cây nhiệt đới', 'granola-trai-cay-nhiet-doi', 135000, 'Granola yến mạch với xoài, thơm, dừa sấy dẻo – vị chua ngọt tự nhiên.', 'images/products/granola-trai-cay-nhiet-doi.webp', 1, 0, 0, '2026-10-20 09:23:00'),
(17, 'NG-BAN-05', 'Sản phẩm', 2, 'Bánh gạo lứt mè đen', 'banh-gao-lut-me-den', 85000, 'Bánh gạo lứt nổ giòn xốp phủ mè đen rang, không chiên, ít béo.', 'images/products/banh-gao-lut-me-den.webp', 1, 0, 0, '2026-10-20 09:23:00'),
(18, 'NG-BAN-06', 'Sản phẩm', 2, 'Thanh protein hạt', 'thanh-protein-hat', 179000, 'Thanh protein từ whey và hạt, 10g protein mỗi thanh, ngọt nhẹ từ chà là.', 'images/products/thanh-protein-hat.webp', 1, 0, 0, '2026-10-20 09:23:00'),
(19, 'NG-GL-04', 'Sản phẩm', 3, 'Mì gạo lứt rau củ', 'mi-gao-lut-rau-cu', 105000, 'Mì gạo lứt trộn bột rau bina, cà rốt, củ dền – 3 màu tự nhiên, không phẩm màu.', 'images/products/mi-gao-lut-rau-cu.webp', 1, 0, 0, '2026-10-20 09:23:00'),
(20, 'NG-GL-05', 'Sản phẩm', 3, 'Gạo lứt đỏ huyết rồng', 'gao-lut-huyet-rong', 129000, 'Gạo lứt đỏ huyết rồng Long An, hạt dài, dẻo nhẹ, giữ nguyên lớp cám.', 'images/products/gao-lut-huyet-rong.webp', 1, 0, 0, '2026-10-20 09:23:00'),
(21, 'NG-CB-1200', 'Combo', 4, 'Combo Giảm cân 1.200', 'combo-giam-can-1200', 308000, 'Bữa sáng granola ít đường, bữa phụ bánh hạt và 1 bộ bún/phở/nui gạo lứt cho bữa chính, đủ dùng 7 ngày.', 'images/products/combo-1200.webp', 0, 1, 0, '2026-09-15 09:23:00'),
