(23, 'NG-CB-1800', 'Combo', 4, 'Combo Tăng cơ 1.800', 'combo-tang-co-1800', 465000, '2 túi granola ít đường, hạt mix 5 loại và 1 bộ bún/phở/nui gạo lứt, nhiều năng lượng cho ngày tập.', 'images/products/combo-1800.webp', 0, 1, 0, '2026-09-15 09:23:00');

-- product: 20 dòng
INSERT INTO product (product_id, package_spec, net_weight_g, ingredients, origin, shelf_life, storage_guide, usage_guide, allergen_note, food_safety_cert) VALUES
(1, 'Hũ 250g', 250, 'Hạnh nhân (30%), hạt điều (25%), óc chó (20%), hạt bí xanh (15%), nam việt quất sấy (10%).', 'Hạnh nhân, óc chó nhập khẩu Mỹ; điều Bình Phước (nay thuộc Đồng Nai); đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Ăn trực tiếp như bữa phụ, rắc lên sữa chua, salad hoặc granola.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-001/2026/NG'),
(2, 'Hũ 250g', 250, '100% hạnh nhân.', 'Hạnh nhân nhập khẩu Mỹ; rang và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Ăn trực tiếp, xay làm sữa hạt hoặc rắc lên yến mạch.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-002/2026/NG'),
(3, 'Hũ 250g', 250, '100% hạt điều.', 'Điều Bình Phước (nay thuộc Đồng Nai); rang và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Ăn trực tiếp như bữa phụ hoặc dùng nấu sữa hạt.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-003/2026/NG'),
(4, 'Túi 300g', 300, 'Yến mạch cán dẹt (55%), hạnh nhân lát (12%), hạt bí xanh (10%), dừa sấy (8%), dầu dừa, erythritol, quế.', 'Phối trộn và nướng tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Dùng với sữa chua không đường hoặc sữa hạt; ăn trực tiếp như snack.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-004/2026/NG'),
(5, 'Túi 300g', 300, 'Yến mạch cán dẹt (55%), hạnh nhân (10%), hạt bí (8%), bột cacao (6%), mật hoa dừa, dầu dừa.', 'Cacao Bến Tre (nay thuộc Vĩnh Long); nướng và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Dùng với sữa tươi không đường hoặc sữa chua.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-005/2026/NG'),
(6, 'Túi 500g', 500, '100% yến mạch nguyên hạt.', 'Yến mạch nhập khẩu Úc; đóng gói tại TP.HCM.', '12 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Nấu với nước/sữa 3–5 phút hoặc ngâm sữa trong tủ lạnh qua đêm.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-006/2026/NG'),
(7, 'Hộp 200g', 200, 'Hạnh nhân lát (40%), hạt bí (15%), hạt hướng dương (15%), lòng trắng trứng, bột yến mạch, erythritol.', 'Sản xuất và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, dưới 30°C. Sau khi mở, cho vào hộp kín, dùng trong 14 ngày.', 'Dùng như bữa phụ cùng trà, cà phê không đường.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-007/2026/NG'),
(8, 'Hộp 250g', 250, 'Bột mì nguyên cám (45%), hạnh nhân (18%), trứng, mật hoa dừa, dầu hướng dương, vani.', 'Sản xuất và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, dưới 30°C. Sau khi mở, cho vào hộp kín, dùng trong 14 ngày.', 'Chấm cà phê, trà hoặc sữa hạt.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-008/2026/NG'),
(9, 'Hộp 200g', 200, 'Yến mạch (40%), bột mì nguyên cám (20%), chuối sấy, bơ, mật hoa dừa, trứng.', 'Sản xuất và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, dưới 30°C. Sau khi mở, cho vào hộp kín, dùng trong 14 ngày.', 'Bữa sáng nhanh cùng sữa hoặc mang theo làm bữa phụ.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-009/2026/NG'),
(10, 'Hộp 10 thanh × 25g', 250, 'Yến mạch (35%), đậu phộng (15%), hạt điều (12%), mật ong, hạt chia, nho khô.', 'Sản xuất và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, dưới 30°C. Sau khi mở, cho vào hộp kín, dùng trong 14 ngày.', 'Ăn trước tập 30–60 phút hoặc thay bữa phụ.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-010/2026/NG'),
(11, 'Bộ 2 gói × 500g', 1000, 'Gạo lứt đỏ (98%), nước, muối.', 'Gạo lứt Đồng Tháp; sản xuất tại Đồng Tháp, đóng gói tại TP.HCM.', '12 tháng kể từ ngày sản xuất', 'Nơi khô ráo, tránh ẩm. Gói đã mở cần kẹp kín.', 'Luộc 5–7 phút trong nước sôi, xả nước lạnh. 80g khô ≈ 1 tô bún.', 'Sản xuất tại cơ sở có chế biến hạt cây, đậu phộng.', 'TCB-NG-011/2026/NG'),
(12, 'Bộ 2 gói × 500g', 1000, 'Gạo lứt (98%), nước, muối.', 'Gạo lứt Đồng Tháp; sản xuất tại Đồng Tháp, đóng gói tại TP.HCM.', '12 tháng kể từ ngày sản xuất', 'Nơi khô ráo, tránh ẩm. Gói đã mở cần kẹp kín.', 'Trụng 3–4 phút trong nước sôi. 80g khô ≈ 1 tô phở.', 'Sản xuất tại cơ sở có chế biến hạt cây, đậu phộng.', 'TCB-NG-012/2026/NG'),
(13, 'Bộ 2 gói × 500g', 1000, 'Gạo lứt (95%), bột năng, nước.', 'Gạo lứt Đồng Tháp; sản xuất tại Đồng Tháp, đóng gói tại TP.HCM.', '12 tháng kể từ ngày sản xuất', 'Nơi khô ráo, tránh ẩm. Gói đã mở cần kẹp kín.', 'Luộc 8–10 phút, xả nước lạnh. 80g khô ≈ 1 đĩa.', 'Sản xuất tại cơ sở có chế biến hạt cây, đậu phộng.', 'TCB-NG-013/2026/NG'),
(14, 'Hũ 250g', 250, '100% óc chó.', 'Óc chó nhập khẩu Mỹ; rang và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Ăn trực tiếp, rắc lên yến mạch, salad hoặc xay sữa hạt.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-014/2026/NG'),
(15, 'Túi 300g', 300, '100% hạt chia.', 'Hạt chia nhập khẩu Úc; đóng gói tại TP.HCM.', '12 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Ngâm 1 muỗng với 150ml nước/sữa 10 phút; trộn sữa chua, sinh tố, overnight oats.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-015/2026/NG'),
(16, 'Túi 300g', 300, 'Yến mạch cán dẹt (50%), xoài sấy (10%), thơm sấy (8%), dừa sấy (8%), hạt điều (8%), mật ong, dầu dừa.', 'Trái cây sấy Tiền Giang; phối trộn và nướng tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, thoáng mát, tránh nắng. Sau khi mở, đậy kín nắp/túi zip kèm gói hút ẩm, dùng trong 30 ngày.', 'Dùng với sữa chua không đường hoặc sữa hạt.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-016/2026/NG'),
(17, 'Túi 200g', 200, 'Gạo lứt (88%), mè đen (8%), muối hồng, dầu gạo.', 'Gạo lứt Đồng Tháp; sản xuất và đóng gói tại TP.HCM.', '9 tháng kể từ ngày sản xuất', 'Nơi khô ráo, dưới 30°C. Sau khi mở, cho vào hộp kín, dùng trong 14 ngày.', 'Ăn trực tiếp hoặc phết bơ đậu phộng, bơ, phô mai ít béo.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-017/2026/NG'),
(18, 'Hộp 8 thanh × 40g', 320, 'Whey protein (22%), hạnh nhân (18%), chà là (18%), yến mạch (15%), hạt điều, cacao, hạt chia.', 'Whey nhập khẩu New Zealand; sản xuất và đóng gói tại TP.HCM.', '6 tháng kể từ ngày sản xuất', 'Nơi khô ráo, dưới 30°C. Sau khi mở, cho vào hộp kín, dùng trong 14 ngày.', 'Ăn sau tập 30 phút hoặc thay bữa phụ.', 'Có chứa hạt cây (hạnh nhân, hạt điều, óc chó). Sản xuất tại cơ sở có chế biến đậu phộng, vừng, sữa.', 'TCB-NG-018/2026/NG'),
(19, 'Bộ 2 gói × 500g', 1000, 'Gạo lứt (90%), bột rau bina, bột cà rốt, bột củ dền, muối.', 'Gạo lứt Đồng Tháp; sản xuất tại Đồng Tháp, đóng gói tại TP.HCM.', '12 tháng kể từ ngày sản xuất', 'Nơi khô ráo, tránh ẩm. Gói đã mở cần kẹp kín.', 'Trụng 4–5 phút trong nước sôi. 80g khô ≈ 1 tô mì.', 'Sản xuất tại cơ sở có chế biến hạt cây, đậu phộng.', 'TCB-NG-019/2026/NG'),
(20, 'Túi 2kg', 2000, '100% gạo lứt huyết rồng.', 'Long An (nay thuộc Tây Ninh); đóng gói tại TP.HCM.', '12 tháng kể từ ngày sản xuất', 'Nơi khô ráo, tránh ẩm. Gói đã mở cần kẹp kín.', 'Ngâm 2 giờ, nấu tỉ lệ 1 gạo : 1,8 nước. 60g gạo ≈ 1 chén cơm.', 'Sản xuất tại cơ sở có chế biến hạt cây, đậu phộng.', 'TCB-NG-020/2026/NG');

