-- blog_post: 6 dòng
INSERT INTO blog_post (post_id, slug, title, topic, summary, content, thumbnail_url, read_minutes, published_at) VALUES
(1, 'cach-tinh-tdee', 'Cách tính TDEE: mỗi ngày bạn cần bao nhiêu calo?', 'Calo & TDEE', 'TDEE là tổng năng lượng cơ thể tiêu hao trong một ngày. Biết con số này, bạn mới chọn được khẩu phần và combo đúng mục tiêu.', '<p><strong>TDEE</strong> (Total Daily Energy Expenditure) là tổng năng lượng bạn tiêu hao trong một ngày, gồm năng lượng duy trì sự sống khi nghỉ ngơi (BMR) và năng lượng cho mọi hoạt động.</p>
<h2>Bước 1: Tính BMR theo công thức Mifflin-St Jeor</h2>
<p>Đây là công thức được dùng phổ biến cho người trưởng thành:</p>
<ul><li>Nam: BMR = 10 × cân nặng (kg) + 6,25 × chiều cao (cm) − 5 × tuổi + 5</li><li>Nữ: BMR = 10 × cân nặng (kg) + 6,25 × chiều cao (cm) − 5 × tuổi − 161</li></ul>
<h2>Bước 2: Nhân với hệ số vận động</h2>
<table><thead><tr><th>Mức vận động</th><th>Hệ số</th></tr></thead><tbody><tr><td>Ít vận động (ngồi văn phòng)</td><td>1,2</td></tr><tr><td>Tập 1–3 buổi/tuần</td><td>1,375</td></tr><tr><td>Tập 3–5 buổi/tuần</td><td>1,55</td></tr><tr><td>Tập 6–7 buổi/tuần</td><td>1,725</td></tr><tr><td>Lao động nặng, tập 2 buổi/ngày</td><td>1,9</td></tr></tbody></table>
<h2>Ví dụ</h2>
<p>Nữ 28 tuổi, cao 158 cm, nặng 55 kg, làm văn phòng: BMR = 550 + 987,5 − 140 − 161 = 1.236,5 kcal. TDEE = 1.236,5 × 1,2 ≈ 1.484 kcal/ngày.</p>
<h2>Bước 3: Điều chỉnh theo mục tiêu</h2>
<p>Muốn giảm cân, nhiều hướng dẫn gợi ý ăn thấp hơn TDEE khoảng 500 kcal/ngày; muốn tăng cơ thì ăn cao hơn một chút và tập kháng lực. Không nên tự cắt quá sâu: dưới khoảng 1.200 kcal/ngày với nữ và 1.500 kcal/ngày với nam thì nên có chuyên gia theo dõi.</p>
<p>Kết quả chỉ là ước tính. Cân nặng thực tế sau 2–3 tuần là thước đo tốt nhất để điều chỉnh tiếp.</p>', 'images/products/yen-mach-can-det.webp', 5, '2026-10-27'),
(2, 'doc-bang-dinh-duong-30-giay', 'Đọc bảng dinh dưỡng trong 30 giây', 'Đọc nhãn & macro', 'Ba con số cần nhìn đầu tiên, và vì sao phải phân biệt “trên 100g” với “trên khẩu phần”.', '<h2>Giây 1–10: Cột “100g” hay “khẩu phần”?</h2>
<p>Cột <strong>trên 100g</strong> dùng để so sánh giữa các sản phẩm. Cột <strong>trên khẩu phần</strong> cho biết lượng bạn thật sự ăn. 100g hạt mix có hơn 600 kcal, nhưng một khẩu phần 30g chỉ khoảng 184 kcal.</p>
<h2>Giây 11–20: Năng lượng và ba chất đa lượng (macro)</h2>
<ul><li>1g protein ≈ 4 kcal</li><li>1g carbohydrate ≈ 4 kcal</li><li>1g chất béo ≈ 9 kcal</li></ul>
<p>Nhân ngược lại, bạn có thể tự kiểm tra con số kcal trên nhãn có hợp lý không. Đây là cách NutriGreen kiểm tra mọi bảng dinh dưỡng trước khi đăng.</p>
<h2>Giây 21–30: Đường và chất xơ</h2>
<p>Dòng <strong>đường</strong> nằm bên trong carbohydrate. Theo chuẩn của Liên minh châu Âu, thực phẩm rắn chỉ được gọi là “ít đường” khi có không quá 5g đường/100g. Chất xơ càng cao, cảm giác no càng lâu.</p>
<p>Trên website NutriGreen, mọi sản phẩm đều có bảng này ở cả hai cột, kèm nguồn số liệu.</p>', 'images/products/granola-it-duong.webp', 4, '2026-10-28'),
(3, 'giau-protein-la-bao-nhieu-gam', '“Giàu protein” là bao nhiêu gam?', 'Đọc nhãn & macro', 'Nhãn “giàu protein” không phải lúc nào cũng có ngưỡng rõ ràng. Đây là cách quy đổi ra con số để so sánh.', '<p>Ở châu Âu, Quy định (EC) 1924/2006 chỉ cho ghi “nguồn protein” khi protein chiếm ít nhất 12% năng lượng của sản phẩm, và “giàu protein” khi chiếm ít nhất 20%. Nhiều sản phẩm bán online tại Việt Nam dùng chữ “giàu protein” mà không kèm con số.</p>
<h2>NutriGreen chọn cách ghi con số</h2>
<p>Thay vì dán nhãn, mỗi thẻ sản phẩm hiện số gam protein trên khẩu phần. Bộ lọc “Protein cao” của website dùng ngưỡng <strong>từ 15g protein/100g</strong> và ghi rõ ngưỡng này để bạn tự đánh giá.</p>
<h2>Bạn cần bao nhiêu protein?</h2>
<ul><li>Người trưởng thành ít vận động: khoảng 0,8g/kg cân nặng/ngày.</li><li>Người tập luyện đều: khoảng 1,4–2,0g/kg/ngày theo khuyến nghị của Hiệp hội Dinh dưỡng Thể thao Quốc tế (ISSN, 2017).</li></ul>
<p>Hạt và granola là nguồn protein bổ sung tiện lợi, nhưng phần lớn protein trong ngày vẫn nên đến từ thịt, cá, trứng, sữa, đậu.</p>', 'images/products/hanh-nhan-rang-moc.webp', 4, '2026-10-30'),
(4, 'duong-an-trong-thuc-pham', 'Đường ẩn trong thực phẩm: nhìn vào đâu?', 'Đọc nhãn & macro', 'Đường không chỉ nằm trong bánh kẹo. Cách tìm đường ẩn trong danh sách thành phần và bảng dinh dưỡng.', '<p>Tổ chức Y tế Thế giới (WHO, 2015) khuyến nghị lượng đường tự do dưới 10% tổng năng lượng mỗi ngày, tốt hơn nữa là dưới 5%. Với khẩu phần 2.000 kcal, 10% tương đương khoảng 50g đường.</p>
<h2>Đường có nhiều tên</h2>
<p>Trong danh sách thành phần, đường có thể xuất hiện dưới tên: đường mía, mật ong, mật hoa dừa, siro glucose, maltodextrin, nước ép trái cây cô đặc. Thành phần được xếp theo khối lượng giảm dần, nên đường càng đứng gần đầu danh sách thì càng nhiều.</p>
<h2>Đọc dòng “đường” trên bảng dinh dưỡng</h2>
<p>So sánh theo cột 100g. Dưới 5g/100g được coi là ít đường theo chuẩn châu Âu. Granola vị cacao của NutriGreen có 9g/100g nên không được gắn nhãn “ít đường”, dù vẫn thấp hơn nhiều loại granola thông thường.</p>', 'images/products/granola-cacao.webp', 4, '2026-10-31'),
(5, 'thuc-don-1200-kcal-dan-van-phong', 'Thực đơn tham khảo khoảng 1.200 kcal cho dân văn phòng', 'Sản phẩm & món ăn', 'Một ngày ăn mẫu kết hợp combo NutriGreen với rau và đạm tươi, kèm số kcal từng bữa.', '<p class="callout">Mức 1.200 kcal/ngày chỉ phù hợp với một số người (thường là nữ, ít vận động). Hãy tính TDEE trước và hỏi ý kiến chuyên gia nếu bạn có bệnh nền, đang mang thai hoặc cho con bú.</p>
<table><thead><tr><th>Bữa</th><th>Món</th><th>kcal (ước tính)</th></tr></thead><tbody>
<tr><td>Sáng</td><td>40g granola ít đường + 100g sữa chua không đường</td><td>≈ 250</td></tr>
<tr><td>Trưa</td><td>80g bún gạo lứt (khô) + 100g ức gà luộc + rau luộc</td><td>≈ 480</td></tr>
<tr><td>Phụ</td><td>2 miếng bánh hạt ăn kiêng (25g) + 1 quả táo</td><td>≈ 220</td></tr>
<tr><td>Tối</td><td>2 quả trứng luộc + 200g rau xanh + canh rau</td><td>≈ 210</td></tr>
<tr><td colspan="2"><strong>Tổng</strong></td><td><strong>≈ 1.160</strong></td></tr></tbody></table>
<p>Số kcal của rau, trứng, ức gà là giá trị ước tính theo USDA FoodData Central; thực tế thay đổi theo cách chế biến và lượng dầu.</p>
<h2>Vì sao combo không “đủ 1.200 kcal”?</h2>
<p>Combo Giảm cân của NutriGreen cung cấp khoảng 859 kcal/ngày. Phần còn lại nên đến từ rau và đạm tươi để bữa ăn đủ vi chất. Chúng tôi ghi rõ con số này trên trang combo.</p>', 'images/products/bun-gao-lut.webp', 5, '2026-11-01'),
(6, 'bun-gao-lut-va-giam-can', 'Bún gạo lứt có giúp giảm cân không?', 'Sản phẩm & món ăn', 'Hiểu đúng để không thất vọng: gạo lứt không “đốt mỡ”, nhưng giúp bạn kiểm soát khẩu phần dễ hơn.', '<p>Tính trên cùng khối lượng khô, bún gạo lứt có năng lượng gần tương đương bún gạo trắng (khoảng 360 kcal/100g). Không có thực phẩm nào tự làm giảm cân; cân nặng thay đổi theo cân bằng năng lượng cả ngày.</p>
<h2>Điểm cộng của gạo lứt</h2>
<ul><li>Giữ lại lớp cám nên có nhiều chất xơ hơn gạo trắng, giúp no lâu hơn.</li><li>Là ngũ cốc nguyên hạt, phù hợp với khuyến nghị ăn đa dạng ngũ cốc.</li></ul>
<h2>Ăn sao cho hợp lý</h2>
<p>Cân 80g khô cho một bữa (khoảng 288 kcal), thêm nhiều rau và một phần đạm. Nếu bạn ăn gấp đôi lượng bún vì “gạo lứt thì lành”, tổng năng lượng vẫn tăng như thường.</p>', 'images/products/pho-gao-lut.webp', 3, '2026-11-02');

